{
  "claims": [
    {
      "id": "C1",
      "text": "The binary task has 2362 development rows, 13 encoded features, no reported missingness, and ROC AUC as the primary metric.",
      "source": ["E1"],
      "polarity": "fact"
    },
    {
      "id": "C2",
      "text": "The policy favors lower complexity unless additional complexity is expected to deliver a clearly better result.",
      "source": [],
      "polarity": "fact"
    },
    {
      "id": "C3",
      "text": "The 13-feature pilot achieved mean ROC AUC 0.9664 with reported variability of ±0.0082.",
      "source": ["E2"],
      "polarity": "fact"
    },
    {
      "id": "C4",
      "text": "The 16-feature pilot achieved the highest observed mean ROC AUC, 0.9717, with reported variability of ±0.0060.",
      "source": ["E2", "E3", "E4", "E5"],
      "polarity": "fact"
    },
    {
      "id": "C5",
      "text": "The 34-feature pilot achieved mean ROC AUC 0.9604 with reported variability of ±0.0143.",
      "source": ["E4"],
      "polarity": "fact"
    },
    {
      "id": "C6",
      "text": "The 23-feature pilot achieved mean ROC AUC 0.9696 with reported variability of ±0.0126.",
      "source": ["E5"],
      "polarity": "fact"
    },
    {
      "id": "C7",
      "text": "All reported evaluations used only a 30% sample and three CV folds, limiting evidence about full-development-data performance.",
      "source": ["E2", "E3", "E4", "E5"],
      "polarity": "concern"
    },
    {
      "id": "C8",
      "text": "The highest-mean pilot did not outperform the 13-feature pilot on every reported fold, so its observed mean advantage is not a uniform fold-level improvement.",
      "source": ["E2", "E3"],
      "polarity": "concern"
    }
  ]
}

{
  "steps": [
